mapper.sql:
WHERE d.del_flag = '0' AND m.del_flag = '0'

	AND d.stock_out_no LIKE CONCAT('%', #{vo.stockOutNo}, '%')


	AND d.goods_name LIKE CONCAT('%', #{vo.goodsName}, '%')


	AND d.goods_code LIKE CONCAT('%', #{vo.goodsCode}, '%')


	AND d.batch_no LIKE CONCAT('%', #{vo.batchNo}, '%')


	AND m.customer_name LIKE CONCAT('%', #{vo.customerName}, '%')


	AND m.warehouse_name LIKE CONCAT('%', #{vo.warehouseName}, '%')


	AND m.warehouse_id =#{vo.warehouseId}


	AND m.status = #{vo.status}


	AND m.approve_status = #{vo.approveStatus}


	AND m.stock_out_type = #{vo.stockOutType}


	AND d.goods_type = #{vo.goodsType}


	AND d.over_flag = #{vo.overFlag}


	AND m.stock_out_time >= #{vo.stockOutTime_begin}


	AND m.stock_out_time <= #{vo.stockOutTime_end}


	AND m.required_date >= #{vo.requiredDate_begin}


	AND m.required_date <= #{vo.requiredDate_end}
